INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66519321', 66519321, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Pemeliharaan Kamera Pengawas pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 6500000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1.0 Thn', 'Melakukan pemeliharaan rutin (preventive) dan perbaikan (corrective) terhadap sistem kamera pengawas (CCTV) untuk memastikan fungsi pengawasan keamanan tetap optimal. Lingkup pekerjaan meliputi pemeriksaan fisik perangkat (kamera, lensa, housing), pemeriksaan koneksi jaringan dan daya (termasuk UPS), verifikasi konfigurasi perekaman (DVR/NVR), penanganan gangguan (troubleshooting), serta dokumentasi dan pelaporan kondisi sistem secara berkala guna mencegah kerusakan mayor dan menjaga kualitas bukti rekaman.', '1. Pemeriksaan Fisik: Pembersihan lensa/housing dari debu/kotoran, pengecekan posisi (angle), dan kekokohan bracket/dudukan. 2. Konektivitas & Daya: Pengecekan kabel (UTP/Coaxial/Fiber), konektor, Switch PoE, adaptor, dan fungsi backup daya (UPS). 3. Sistem & Konfigurasi: Memastikan DVR/NVR merekam sesuai jadwal, kualitas gambar (resolusi/frame rate) jelas, kapasitas penyimpanan (storage) memadai, dan update firmware jika tersedia. 4. Troubleshooting (Korektif): Penanganan kamera mati/hilang sinyal (no signal), reset konfigurasi error, serta penggantian kabel/konektor atau unit yang rusak. 5. Dokumentasi: Pencatatan lokasi, hasil perbaikan, dan laporan status kapasitas penyimpanan serta backup data penting.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2828264);
